// Extract Droid ID from MQTT topic
const topicSegments = (msg.topic || '').split('/');
const droidId = topicSegments[1] || msg.payload.droid_id || 'UNKNOWN_DROID';

const raw = msg.payload;
const incidentId = 'INC-' + Date.now().toString(36).toUpperCase();
const timestamp = raw.timestamp || new Date().toISOString();

// Determine severity based on sensor triggers
let severity = 'WARNING';
let requiresLockdown = false;

const eventType = raw.event_type || 'UNKNOWN_TAMPER_EVENT';

if (eventType.includes('PRIED_OPEN') || 
    eventType.includes('CHASSIS_BREACH') || 
    eventType.includes('FORCE_ENTRY') ||
    raw.sensors?.compartment_switch === 'BREACHED') {
    severity = 'CRITICAL';
    requiresLockdown = true;
} else if (eventType.includes('MULTIPLE_UNAUTHORIZED_RFID') || raw.sensors?.rfid_failed_count >= 3) {
    severity = 'HIGH';
    requiresLockdown = true;
} else if (raw.sensors?.vibration_g > 3.0 || raw.sensors?.imu_tilt_deg > 45) {
    severity = 'WARNING';
}

// Build standardized security audit record
const auditRecord = {
    incident_id: incidentId,
    droid_id: droidId,
    timestamp: timestamp,
    severity: severity,
    event_type: eventType,
    details: raw.details || raw.reason || 'Sensor limit switch tripped without authorized unlock',
    location: {
        lat: raw.location?.latitude || raw.location?.lat || -29.8587,
        lon: raw.location?.longitude || raw.location?.lon || 31.0218,
        alt_m: raw.location?.altitude_m || 120.0
    },
    sensors: {
        compartment_locked: raw.sensors?.compartment_locked ?? true,
        door_switch_state: raw.sensors?.door_switch || 'OPEN',
        rfid_failed_count: raw.sensors?.rfid_failed_count || 0,
        tilt_deg: raw.sensors?.imu_tilt_deg || 0,
        shock_g: raw.sensors?.vibration_g || 0
    },
    battery_pct: raw.battery_soc_pct || raw.battery?.soc_pct || 85
};

// Message 1 (Out 1): Formatted record for File Logger & Debug
// Message 2 (Out 2): Automated Countermeasure (Lockdown command over MQTT)
const logMsg = {
    ...msg,
    payload: auditRecord,
    incident_id: incidentId,
    severity: severity
};

let countermeasureMsg = null;
if (requiresLockdown) {
    countermeasureMsg = {
        topic: `droid/${droidId}/command/lockdown`,
        payload: {
            command: 'ENGAGE_EMERGENCY_LOCKDOWN',
            incident_id: incidentId,
            droid_id: droidId,
            timestamp: new Date().toISOString(),
            actions: {
                energize_secondary_deadbolt: true,
                sound_alarm_siren: true,
                flash_strobe_leds: true,
                disable_drive_motors: true,
                capture_camera_snapshot: true
            }
        }
    };
}

return [logMsg, countermeasureMsg];

// Format as single-line JSON with trailing newline for continuous append
msg.payload = JSON.stringify(msg.payload) + '\n';
return msg;
